   492  #define ENV_VAR_NAME_LEN_MAX 64
   493
   494  static __attribute__((noinline)) const char *secure_getenv_len(const char *key, size_t len)
   495  {
   496      if (UNLIKELY(len > ENV_VAR_NAME_LEN_MAX)) {
   497          lwan_status_error("Variable name exceeds %d bytes", ENV_VAR_NAME_LEN_MAX);
   498          return NULL;
   499      }
   500
   501      return secure_getenv(strndupa(key, len));
   502  }
