   598  static void *parse_section(struct parser *parser)
   599  {
   600      struct lexeme *lexeme;
   601      size_t name_len;
   602
   603      if (!lexeme_buffer_consume(&parser->buffer, &lexeme))
   604          return NULL;
   605
   606      lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value, lexeme->value.len);
   607      name_len = lexeme->value.len;
   608      lwan_strbuf_append_char(&parser->strbuf, '\0');
   609
   610      while (lexeme_buffer_consume(&parser->buffer, &lexeme)) {
   611          lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value, lexeme->value.len);
   612
   613          if (!lexeme_ring_buffer_empty(&parser->buffer))
   614              lwan_strbuf_append_char(&parser->strbuf, ' ');
   615      }
   616
   617      struct config_line line = {
   618          .type = CONFIG_LINE_TYPE_SECTION,
   619          .key = lwan_strbuf_get_buffer(&parser->strbuf),
   620          .value = lwan_strbuf_get_buffer(&parser->strbuf) + name_len + 1
   621      };
   622      if (!config_buffer_emit(&parser->items, &line))
   623          return NULL;
   624
   625      return parse_config;
   626  }
