   628  static void *parse_section_shorthand(struct parser *parser)
   629  {
   630      void *next_state = parse_section(parser);
   631
   632      if (next_state) {
   633          struct config_line line = { .type = CONFIG_LINE_TYPE_SECTION_END };
   634
   635          if (!config_buffer_emit(&parser->items, &line))
   636              return NULL;
   637
   638          return next_state;
   639      }
   640
   641      return NULL;
   642  }
