   644  static void *parse_config(struct parser *parser)
   645  {
   646      struct lexeme *lexeme;
   647
   648      if (!lex_next(&parser->lexer, &lexeme))
   649          return NULL;
   650
   651      switch (lexeme->type) {
   652      case LEXEME_EQUAL:
   653          return parse_key_value;
   654
   655      case LEXEME_OPEN_BRACKET:
   656          return parse_section;
   657
   658      case LEXEME_LINEFEED:
   659          if (!lexeme_ring_buffer_empty(&parser->buffer))
   660              return parse_section_shorthand;
   661
   662          return parse_config;
   663
   664      case LEXEME_STRING:
   665          lexeme_buffer_emit(&parser->buffer, lexeme);
   666
   667          return parse_config;
   668
   669      case LEXEME_CLOSE_BRACKET: {
   670          struct config_line line = { .type = CONFIG_LINE_TYPE_SECTION_END };
   671
   672          config_buffer_emit(&parser->items, &line);
   673
   674          return parse_config;
   675      }
   676
   677      case LEXEME_EOF:
   678          return NULL;
   679
   680      default:
   681          lwan_status_error("Unexpected lexeme type: %s",
   682              lexeme_type_str[lexeme->type]);
   683          return NULL;
   684      }
   685  }
