   687  static bool parser_next(struct parser *parser, struct config_line **line)
   688  {
   689      while (parser->state) {
   690          if (config_buffer_consume(&parser->items, line))
   691              return true;
   692
   693          lwan_strbuf_reset(&parser->strbuf);
   694
   695          parser->state = parser->state(parser);
   696      }
   697
   698      return config_buffer_consume(&parser->items, line);
   699  }
