   701  static struct config *
   702  config_open_path(const char *path, void **data, size_t *size)
   703  {
   704      struct config *config;
   705      struct stat st;
   706      void *mapped;
   707      int fd;
   708
   709      fd = open(path, O_RDONLY | O_CLOEXEC);
   710      if (fd < 0) {
   711          lwan_status_perror("Could not open configuration file: %s", path);
   712          return NULL;
   713      }
   714
   715      if (fstat(fd, &st) < 0) {
   716          close(fd);
   717          return NULL;
   718      }
   719
   720      mapped = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_SHARED, fd, 0);
   721      close(fd);
   722      if (mapped == MAP_FAILED)
   723          return NULL;
   724
   725      config = malloc(sizeof(*config));
   726      if (!config) {
   727          munmap(mapped, (size_t)st.st_size);
   728          return NULL;
   729      }
   730
   731      *data = config->mapped.addr = mapped;
   732      *size = config->mapped.sz = (size_t)st.st_size;
   733
   734      return config;
   735  }
